ProjectALife.DialogueShards["barks_aimed_1"] = {
{"AIMED_AT","reg=civilian,family|tmp=fresh",{"Don't, don't, I'm gonna stand real still, and you're gonna think about it","It's on my chest, I can see down the middle of it - I can see all the way down","Just tell me where to put my hands, I'll put 'em there","I lost my wife on the ninth, my girl on the tenth - Point that somewhere else, okay?","My daughter's name is June, I just want somebody in this county to know it","I'm not moving, see, I'm not moving- just don't","You don't gotta do this, {g:man|lady}, please, you don't gotta","Please... give me a minute to think","Oh God, okay - hi - hello - I'm friendly - I'm friendly","That's a {weapon}, my daddy had one - he'd be sick to see this","There's a kid at the Kelso place gonna wait up all night for me","My legs went, I'm going down, I'm not trying anything, my legs just went","I'll turn around - you want me turned around? I'll turn around","Please, {mister}, please, I got nothing else to say to you","If you're gonna do it, don't do it while I'm looking at you - that's all I ask","You want my hands up? Say the words, I'll do anything you say the words for"}},
{"AIMED_AT","reg=civilian|tmp=fresh",{"Is that loaded? No - don't answer, I don't want to know","Please, there's nobody left to tell, if you do it","Whatever you think I did, I didn't - Point it down and I'll say I did"}},
{"AIMED_AT","reg=civilian|tmp=fresh,seasoned",{"If you're gonna, do it quick, I've watched slow - slow is awful"}},
{"AIMED_AT","reg=civilian,worker|tmp=fresh,seasoned",{"Easy with that! I don't want an accident"}},
{"AIMED_AT","reg=civilian,worker,family",{"Don't shoot. The noise could bring more of those things","Alright, hold on - hold on - let me set this down first"}},
{"AIMED_AT","role=civilian_loner",{"I was gonna say hello. Guess I'll wait"}},
{"AIMED_AT","reg=family",{"Please, lower it. I don't know what else to say","My boy's seven and he's watching - Point it at the dirt - for him","Take the house, take all of it, just don't do it in the house"}},
{"AIMED_AT","role=family_woman",{"I'm somebody's mother, I know that don't matter, I'm saying it anyway"}},
{"AIMED_AT","reg=family|tmp=seasoned",{"Go on. Tell me what this is about"}},
{"AIMED_AT","role=family_elder",{"I'm eighty-one, {g:son|young lady}, you'd be robbing a tombstone"}},
{"AIMED_AT","role=family_youth",{"Is that real? That's real, oh God, that's a real one"}},
{"AIMED_AT","reg=worker|tmp=seasoned",{"Point that away, or use it, I don't do the middle part","Careful with that thing. You trying to scare me?","Twenty-two years around men with guns, not one of 'em ever pointed it"}},
{"AIMED_AT","reg=worker",{"Put that down. Talk to me like a person"}},
{"AIMED_AT","reg=worker|mood=funny",{"I've got a wife, two dogs and a bad back - which one you want?"}},
{"AIMED_AT","reg=worker,civilian|tmp=seasoned",{"Muzzle's on my belly, that's a bad way to go - ask anybody"}},
{"AIMED_AT","reg=worker,outlaw|tmp=seasoned",{"If you're just showing me the gun, I've seen it - it's a fine gun"}},
{"AIMED_AT","reg=civilian,worker,outlaw|tmp=seasoned",{"You're shaking, that's the part that worries me, not you, the shaking","Alright, say what you want - I'm listening real good now","It goes off by accident, they come, then it don't matter who was right"}},
{"AIMED_AT","reg=civilian,worker,law|tmp=seasoned,veteran",{"Your finger's on the trigger - put it on the guard, for both of us"}},
{"AIMED_AT","reg=civilian,worker|tmp=seasoned",{"You're gonna hold that on me all day?"}},
{"AIMED_AT","reg=civilian,worker,crime|tmp=seasoned",{"You've pointed it, you've made your point - so now what?"}},
{"AIMED_AT","reg=civilian,worker|tmp=seasoned|mood=funny",{"Well, ain't this a fine way to meet a neighbor - heh"}},
{"AIMED_AT","reg=outlaw,worker|tmp=seasoned",{"I got nothing worth that bullet, you'd be throwing good brass at a bad man"}},
{"AIMED_AT","role=rescue_medical",{"Point it down. I have enough to worry about","You shoot me and the next person with a cut dies too - that's just math"}},
{"AIMED_AT","role=rescue_clergy",{"{g:Son|Young lady}, I've anointed three men this week - don't make me a fourth"}},
{"AIMED_AT","role=rescue_firefighter",{"I'm holding a burn kit - you want to shoot a man holding a burn kit?"}},
{"AIMED_AT","reg=rescue",{"That barrel's touching my coat - back it up a foot and we'll talk"}},
{"AIMED_AT","reg=rescue,law|tmp=seasoned,veteran",{"Your hand's steady, that tells me more about you than anything you'd say"}},
{"AIMED_AT","reg=law",{"{sir}, lower the weapon - I'm not going to say it in a nicer voice"}},
{"AIMED_AT","role=law_deputy",{"Point that at a deputy and everything after is yours, not mine"}},
{"AIMED_AT","role=law_sheriff",{"You're aiming a gun at the sheriff of this county - take a second on that"}},
{"AIMED_AT","reg=law|tmp=veteran",{"I've had guns on me since '76, nobody who pointed one felt better after","This goes one of two ways and you're picking - pick slow","{g:Son|Young lady}, the last man who aimed at me in this county is buried in Rosewood"}},
{"AIMED_AT","reg=law,swat",{"Hand off the trigger, thumb the safety, you know how or you wouldn't hold it"}},
{"AIMED_AT","reg=law|tmp=seasoned",{"I'm not drawing - see? Hand's out, now you do your half"}},
{"AIMED_AT","role=law_trooper",{"Trooper, unit {unit}, if I quit talking, somebody comes looking for me"}},
{"AIMED_AT","role=law_sergeant,law_sheriff",{"Lower it. You've got my attention"}},
{"AIMED_AT","role=law_corrections",{"Corrections, I've been shanked, spit on and shot at - lower it"}},
{"AIMED_AT","reg=swat",{"Weapon on me - lower it now, or my team ends this","Look at me. Lower that weapon"}},
{"AIMED_AT","role=swat_lead",{"Muzzle down - now - count of one"}},
{"AIMED_AT","role=swat_operator",{"You lower that, this is a conversation, you don't, it isn't"}},
{"AIMED_AT","reg=military",{"Watch that muzzle, civilian! Point it at the ground!"}},
{"AIMED_AT","reg=military|tmp=seasoned|world=road",{"You're pointing a rifle at a United States soldier on a road in Kentucky"}},
{"AIMED_AT","reg=military|tmp=veteran",{"Weapon down, I don't want to write a report I can't send anywhere"}},
{"AIMED_AT","role=soldier_nco",{"Point it away. I won't ask twice"}},
