{"AIMED_AT","reg=military|tmp=seasoned",{"You've got one barrel - count ours - go ahead and count 'em"}},
{"AIMED_AT","reg=military,elite|tmp=veteran",{"Lower it, or I make it a fair fight, fair means nobody walks"}},
{"AIMED_AT","role=deserter",{"Hey! Hey, I'm out! I'm not in the Army anymore! Point it down!"}},
{"AIMED_AT","role=elite_delta",{"Muzzle - down","Sights off me - now"}},
